static TestProc initr(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc snapc(const char*r,const char*s,const char*t,const char*cfg){const char*a[14];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;if(cfg){a[n++]="--config";a[n++]=cfg;}a[n++]="snapshot";a[n++]="create";a[n++]=s;a[n++]="--timestamp";a[n++]=t;a[n]=NULL;return test_exec(a,NULL);}
static TestProc restor(const char*r,const char*sel,const char*to,const char*path,const char*ow,const char*fmt,const char*const env[]){const char*a[18];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;if(fmt){a[n++]="--format";a[n++]=fmt;}a[n++]="restore";a[n++]=sel;a[n++]="--to";a[n++]=to;if(path){a[n++]="--path";a[n++]=path;}if(ow){a[n++]="--overwrite";a[n++]=ow;}a[n]=NULL;return test_exec(a,env);}
static bool setmtime(const char*p,int64_t ns){struct timespec t[2]={{.tv_sec=(time_t)(ns/1000000000LL),.tv_nsec=(long)(ns%1000000000LL)},{.tv_sec=(time_t)(ns/1000000000LL),.tv_nsec=(long)(ns%1000000000LL)}};return utimensat(AT_FDCWD,p,t,AT_SYMLINK_NOFOLLOW)==0;}
static bool readlinkeq(const char*p,const char*want){char b[1024];ssize_t n=readlink(p,b,sizeof b);return n==(ssize_t)strlen(want)&&!memcmp(b,want,(size_t)n);}
static bool load_file_at(const char*r,const char*sel,const char*path,DarcFileObj*f,DarcCid*fc){DarcCid sid;DarcSnapshotObj s={0};DarcFlatTree t={0};if(darc_resolve_snapshot(r,sel,&sid,&s)||darc_flatten_snapshot(r,&s,&t)){darc_snapshot_free(&s);return false;}DarcFlatEnt*e=darc_flat_find(&t,path);bool ok=false;if(e&&(e->type==1||e->type==4)){*fc=e->cid;DarcObject o;if(!darc_object_load(r,&e->cid,&o,1)&&o.type==OBJ_FILE){ok=!darc_file_parse(o.payload.data,o.payload.len,f);darc_object_free(&o);}}darc_flat_free(&t);darc_snapshot_free(&s);return ok;}
static bool remove_obj(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);bool ok=p&&unlink(p)==0;free(p);return ok;}
static bool flip_obj(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);if(!p)return false;int fd=open(p,O_RDWR|O_CLOEXEC);struct stat st;bool ok=fd>=0&&!fstat(fd,&st)&&st.st_size>36;if(ok){uint8_t b;off_t o=st.st_size-1;if(pread(fd,&b,1,o)!=1)ok=false;else{b^=0x80;if(pwrite(fd,&b,1,o)!=1||fsync(fd))ok=false;}}if(fd>=0)close(fd);free(p);return ok;}
static bool writepat(const char*p,size_t n){int fd=open(p,O_CREAT|O_TRUNC|O_WRONLY|O_CLOEXEC,0644);if(fd<0)return false;uint8_t b[65536];size_t off=0;while(off<n){size_t z=n-off<sizeof b?n-off:sizeof b;for(size_t i=0;i<z;i++)b[i]=(uint8_t)(((off+i)*73u)^((off+i)>>8));if(darc_write_all(fd,b,z)){close(fd);return false;}off+=z;}return close(fd)==0;}
/* Raw object fixture writer: builds the disk frame directly rather than calling darc_object_store. */
static bool raw_object(const char*r,uint8_t type,const uint8_t*p,size_t n,DarcCid*out){darc_object_cid(type,p,n,out);char h[65];darc_cid_hex(out,h);char rel[96];snprintf(rel,sizeof rel,"objects/sha256/%.2s",h);char*dir=test_path(r,rel);if(!dir||test_mkdir(dir)){free(dir);return false;}char*fp=darc_object_path(r,out);free(dir);if(!fp)return false;DarcBuf b;darc_buf_init(&b);bool bad=darc_buf_put(&b,"DARCOBJ1",8)||darc_buf_u8(&b,type)||darc_buf_u8(&b,0)||darc_buf_u16(&b,0)||darc_buf_u64(&b,(uint64_t)n)||darc_buf_u64(&b,(uint64_t)n);if(!bad)bad=darc_buf_u32(&b,darc_crc32c(b.data+8,20))||darc_buf_put(&b,p,n)||darc_buf_u32(&b,darc_crc32c(p,n));bool ok=!bad&&!test_write(fp,b.data,b.len,0644);darc_buf_free(&b);free(fp);return ok;}
static bool publish_manual(const char*r,const DarcCid*root,uint64_t files,DarcCid*out){DarcSnapshotObj s;memset(&s,0,sizeof s);s.created_ns=777;s.root=*root;s.root_mode=0755;s.root_mtime_ns=0;s.root_n=1;s.roots=calloc(1,sizeof(char*));if(!s.roots)return false;s.roots[0]=strdup("manual");s.files=files;DarcBuf p;bool ok=!darc_snapshot_serialize(&s,&p)&&raw_object(r,OBJ_SNAPSHOT,p.data,p.len,out);darc_buf_free(&p);darc_snapshot_free(&s);if(!ok)return false;char h[65],rel[128],line[66];darc_cid_hex(out,h);snprintf(rel,sizeof rel,"refs/snapshots/%s",h);char*rf=test_path(r,rel),*hd=test_path(r,"HEAD");snprintf(line,sizeof line,"%s\n",h);ok=rf&&hd&&!test_write(rf,line,65,0644)&&!test_write(hd,line,65,0644);free(rf);free(hd);return ok;}
static bool manual_file_snapshot(const char*r,const uint8_t*name,size_t nl,bool bad_digest,DarcCid*snapid){const uint8_t content[]="payload";DarcCid cc;if(!raw_object(r,OBJ_CHUNK,content,sizeof(content)-1,&cc))return false;DarcFileObj f;memset(&f,0,sizeof f);f.logical_size=sizeof(content)-1;f.chunk_n=1;f.chunks=calloc(1,sizeof* f.chunks);if(!f.chunks)return false;f.chunks[0].cid=cc;f.chunks[0].len=sizeof(content)-1;DarcSha256 sh;darc_sha256_init(&sh);darc_sha256_update(&sh,content,sizeof(content)-1);darc_sha256_final(&sh,f.digest);if(bad_digest)f.digest[0]^=1;DarcBuf fp;bool ok=!darc_file_serialize(&f,&fp);darc_file_free(&f);DarcCid fc;if(ok)ok=raw_object(r,OBJ_FILE,fp.data,fp.len,&fc);darc_buf_free(&fp);if(!ok)return false;DarcBuf tp;darc_buf_init(&tp);ok=!darc_buf_u16(&tp,1)&&!darc_buf_u64(&tp,1)&&!darc_buf_u64(&tp,(uint64_t)nl)&&!darc_buf_put(&tp,name,nl)&&!darc_buf_u8(&tp,1)&&!darc_buf_u32(&tp,0644)&&!darc_buf_i64(&tp,0)&&!darc_buf_put(&tp,fc.b,32)&&!darc_buf_u64(&tp,0);DarcCid tc;if(ok)ok=raw_object(r,OBJ_TREE,tp.data,tp.len,&tc);darc_buf_free(&tp);return ok&&publish_manual(r,&tc,1,snapid);}

